  "Type or snap the homework, then tap Teach me on a problem.": "होमवर्क लिखें या उसकी फ़ोटो लें, फिर किसी सवाल पर “सिखाओ” दबाएँ।",
  "Your words": "आपके शब्द",
  "learned": "सीखे",
  "The words your trade uses, that a general model gets wrong every time. Teach it once and it never gets them wrong again — in answers, documents and translations alike. This is the part of the app that gets better the longer you use it, and the part nobody can copy.": "आपके काम के वो शब्द जिन्हें एक आम मॉडल हर बार गलत करता है। एक बार सिखा दें और ये फिर कभी गलती नहीं करेगा — जवाबों, डॉक्यूमेंट और अनुवाद सब में। ये ऐप का वो हिस्सा है जो जितना इस्तेमाल करें उतना बेहतर होता है, और जिसकी कोई नकल नहीं कर सकता।",
  "the word (سطحة, mobilisation…)": "शब्द (سطحة, mobilisation…)",
  "how you want it written": "आप इसे कैसे लिखा हुआ चाहते हैं",
  "Teach it": "सिखाएँ",
  "or save the first box as a writing rule — “always state VAT separately”": "या पहले बॉक्स को लिखने के नियम की तरह सेव करें — “VAT हमेशा अलग से बताओ”",
  "Nothing yet. The fastest way to start: when an answer uses the wrong word, tap “a word is wrong” under it.": "अभी कुछ नहीं। शुरू करने का सबसे तेज़ तरीका: जब किसी जवाब में गलत शब्द हो, उसके नीचे “कोई शब्द गलत है” दबाएँ।",
  "What it has learned from your corrections": "आपके सुधारों से इसने क्या सीखा",
  "kept": "रखा",
  "Correct a few answers first.": "पहले कुछ जवाब सुधारें।",
