  "Paste a message or write a site note, and anything you promised in it shows up here.": "कोई मैसेज पेस्ट करें या साइट नोट लिखें, और उसमें आपने जो भी वादा किया वो यहाँ दिखेगा।",
  "Read what's in Instant for promises": "Instant में जो है उसमें वादे ढूँढें",
  "Every item carries the exact words it came from. If those words aren't in what you wrote, it never gets here — the app can miss something, but it cannot make one up.": "हर चीज़ के साथ वही शब्द होते हैं जिनसे वो आई। अगर वो शब्द आपके लिखे में नहीं हैं, तो वो यहाँ कभी नहीं आती — ऐप कुछ छोड़ सकता है, लेकिन कुछ गढ़ नहीं सकता।",
