  "When you ask for a fact, Chat first looks it up in your sources and shows which one it used.": "जब आप कोई तथ्य पूछते हैं, Chat पहले उसे आपके सोर्स में ढूँढता है और दिखाता है कि कौन सा इस्तेमाल किया।",
