  "Chat looks these up before it answers, and shows the source. They download by themselves when you are online and stay up to date.": "Chat जवाब देने से पहले इनमें ढूँढता है, और सोर्स दिखाता है। ऑनलाइन होने पर ये अपने आप डाउनलोड होते हैं और अपडेट रहते हैं।",
