  "Stop": "रोकें",
  "Describe it in one sentence — the AI on your phone writes a designed PowerPoint or a full report, from the web or your own file. Edit any slide, then save it as PowerPoint, Word or PDF.": "एक वाक्य में बताएँ — आपके फ़ोन का AI एक डिज़ाइन किया हुआ PowerPoint या पूरी रिपोर्ट लिखता है, वेब से या आपकी अपनी फ़ाइल से। कोई भी स्लाइड बदलें, फिर PowerPoint, Word या PDF में सेव करें।",
