  "Build a CV in English or Arabic, keep a copy for every job, and export a clean PDF or Word file. The AI on your phone helps with wording.": "अंग्रेज़ी या अरबी में CV बनाएँ, हर नौकरी के लिए एक कॉपी रखें, और साफ़ PDF या Word फ़ाइल एक्सपोर्ट करें। आपके फ़ोन का AI शब्दों में मदद करता है।",
  "New CV": "नया CV",
