  "Pro is bought in the Google Play version of Attune — one tap, paid by card or from your {c} balance, and it switches on by itself.": "Pro, Attune के Google Play वर्ज़न में खरीदा जाता है — एक टैप, कार्ड से या अपने {c} बैलेंस से भुगतान, और यह अपने-आप चालू हो जाता है।",
