  "Free: keep and search everything. Pro: it files each item by itself (title, summary, tags), reads your photos and answers questions from your Mind.": "फ़्री: सब कुछ रखें और खोजें। Pro: हर चीज़ को अपने-आप सही जगह रखता है (टाइटल, सारांश, टैग), आपकी फ़ोटो पढ़ता है और आपके Mind से सवालों के जवाब देता है।",
