  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "इसे पता है कि यहाँ असल में चीज़ें कैसे चलती हैं — सही कीमतें, आम तौर पर ज़्यादा वसूली, क्या बदतमीज़ी माना जाता है। जिस बात के लिए लाइव डेटा चाहिए जो ऑफ़लाइन नहीं मिल सकता, वह आपको बता देगा।",
