  "e.g. LTM 1200 (unit 3), Demag AC 100, XCMG QY50KA — 'Crane 3' means unit 3": "जैसे: LTM 1200 (यूनिट 3), Demag AC 100, XCMG QY50KA — 'क्रेन 3' यानी यूनिट 3",
  "Internal terms & abbreviations": "अंदरूनी शब्द और संक्षेप",
  "e.g. PTW = permit to work, 'the yard' = North Gate, LO = lift operation": "जैसे: PTW = काम की अनुमति, 'यार्ड' = नॉर्थ गेट, LO = लिफ़्ट ऑपरेशन",
