  "Turns logged downtime into a figure you can put in front of management.": "दर्ज डाउनटाइम को ऐसे आँकड़े में बदलता है जो आप मैनेजमेंट के सामने रख सकें।",
  "Reporting rules": "रिपोर्टिंग के नियम",
  "e.g. every incident must state whether work was stopped; always record permit number": "जैसे: हर घटना में लिखें कि काम रुका या नहीं; परमिट नंबर हमेशा दर्ज करें",
  "This is added to every field document — and it's also what your own adapter trains on, so the model learns your operation, not a generic one.": "यह हर फ़ील्ड दस्तावेज़ में जुड़ता है — और आपका अपना एडेप्टर भी इसी से सीखता है, ताकि मॉडल आपका काम समझे, कोई आम काम नहीं।",
