  "Merge": "मिलाएँ",
  "Keep everything on this phone and add the backup's chats, memory, reminders and cycle days. The Money ledger is only taken from the backup if this phone has none.": "इस फ़ोन का सब कुछ रखें और बैकअप की चैट, मेमोरी, रिमाइंडर और साइकिल के दिन जोड़ दें। पैसे की बही बैकअप से तभी ली जाती है जब इस फ़ोन में कोई बही न हो।",
  "This phone's {c} chats and {l} ledger entries will be replaced by the backup's. You can undo this once, right after.": "इस फ़ोन की {c} चैट और {l} बही एंट्री बैकअप वाली से बदल दी जाएँगी। इसके ठीक बाद आप इसे एक बार पहले जैसा कर सकते हैं।",
  "The backup's items will be added to this phone. You can undo this once, right after.": "बैकअप के आइटम इस फ़ोन में जोड़ दिए जाएँगे। इसके ठीक बाद आप इसे एक बार पहले जैसा कर सकते हैं।",
