  "Stops invented facts": "गढ़े हुए तथ्य रोकता है",
  "No model is loaded. Open Engine in Attune and load one.": "कोई मॉडल लोड नहीं है। Attune में इंजन खोलें और एक लोड करें।",
  "Attune does not answer that kind of request.": "Attune ऐसे अनुरोध का जवाब नहीं देता।",
  "Suggested. The free tier stops when it runs out instead of charging you.": "सुझाया गया। फ़्री टियर खत्म होने पर रुक जाता है, आपसे पैसे नहीं लेता।",
  "Needs a card on file. An independent index — good in English, unproven in Arabic.": "कार्ड फ़ाइल पर चाहिए। एक स्वतंत्र इंडेक्स — अंग्रेज़ी में अच्छा, अरबी में अभी परखा नहीं गया।",
  "Returns Google's own results, so the best Arabic quality of the three.": "Google के अपने नतीजे देता है, इसलिए तीनों में अरबी की सबसे अच्छी क्वालिटी।",
