  "What should I check on a used car before I buy it?": "सेकंड-हैंड कार खरीदने से पहले क्या जाँचना चाहिए?",
  "My period started this morning, medium flow": "मेरा पीरियड आज सुबह शुरू हुआ, मध्यम फ़्लो",
  "Add it to your ledger in Money? You'll pick the account and confirm there.": "इसे पैसे की बही में जोड़ें? अकाउंट वहीं चुनकर पक्का करना होगा।",
