  "3 templates · 5 history items": "3 टेम्पलेट · 5 इतिहास आइटम",
  "35B of knowledge, 3B doing the work on each token — near-frontier answers at a speed a laptop can sustain. A mixture-of-experts model keeps every expert in memory even though few run per token, so this needs the RAM of a 35B and the compute of a 3B.": "35B जानकारी, हर टोकन पर 3B काम करता है — लैपटॉप जितनी रफ़्तार पर लगभग सबसे आगे वाले जवाब। मिक्सचर-ऑफ़-एक्सपर्ट्स मॉडल हर टोकन पर कुछ ही एक्सपर्ट चलाता है पर सब मेमोरी में रखता है, इसलिए इसे 35B जितनी RAM और 3B जितना कंप्यूट चाहिए।",
  "A bigger length budget for reports, plans and analysis.": "रिपोर्ट, प्लान और विश्लेषण के लिए लंबी जवाब-सीमा।",
  "Ask it as much as you like — no daily limit": "जितना चाहें पूछें — रोज़ की कोई सीमा नहीं",
  "Your phone reports {n} GB of memory": "आपका फ़ोन {n} GB मेमोरी बताता है",
  "Your computer reports {n} GB of memory": "आपका कंप्यूटर {n} GB मेमोरी बताता है",
  "which is comfortable for everyday use": "जो रोज़ के इस्तेमाल के लिए आरामदायक है",
  "which is enough, with shorter conversations": "जो काफ़ी है, छोटी बातचीत के साथ",
  ", ": ", ",
  "Documents, fleet records, copilot, every domain pack": "दस्तावेज़, फ़्लीट रिकॉर्ड, कोपायलट, हर डोमेन पैक",
  "Small enough to download on mobile data if you need to.": "इतना छोटा कि ज़रूरत हो तो मोबाइल डेटा पर भी डाउनलोड हो जाए।",
  "This is a large model for a phone. It will run, and it will slow down noticeably once the phone gets warm — keep answers short, or pick the smaller one.": "यह फ़ोन के लिए बड़ा मॉडल है। चलेगा, पर फ़ोन गर्म होते ही साफ़ धीमा हो जाएगा — जवाब छोटे रखें, या छोटा मॉडल चुनें।",
  "Every tool, and all 31 country packs": "हर टूल, और सभी 31 कंट्री पैक",
  "Finds what you promised people, from your own words": "आपके अपने शब्दों से ढूँढता है कि आपने लोगों से क्या वादा किया था",
  "Fixed randomness, so a workflow gives identical output every time it runs.": "तय रैंडमनेस, ताकि वर्कफ़्लो हर बार एक जैसा आउटपुट दे।",
  "Free web search: DuckDuckGo, Bing and Mojeek at once, then the top pages are read in full, so answers come from real passages.": "मुफ़्त वेब खोज: DuckDuckGo, Bing और Mojeek एक साथ, फिर टॉप पेज पूरे पढ़े जाते हैं, इसलिए जवाब असली अंशों से आते हैं।",
  "Free · no key": "मुफ़्त · कुंजी नहीं चाहिए",
  "Installing… {p}%": "इंस्टॉल हो रहा है… {p}%",
  "It remembers everything and can search it": "यह सब याद रखता है और खोज सकता है",
  "Learns your vocabulary and writes the way you do": "आपकी शब्दावली सीखता है और आपकी तरह लिखता है",
  "No account, no sign-in, nothing uploaded": "कोई अकाउंट नहीं, कोई साइन-इन नहीं, कुछ अपलोड नहीं",
  "Running": "चल रहा है",
  "Loading the model…": "मॉडल लोड हो रहा है…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "ऐप में कुछ भी इंटरनेट तक नहीं पहुँच सकता — न वेब खोज, न मैप, न डाउनलोड। मॉडल और फ़ोन की हर चीज़ चलती रहती है।",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "मॉडल हर सवाल पर पहले सोचता है। कठिन सवालों पर साफ़ बेहतर, पर फ़ोन पर जवाब 30–90 सेकंड देर से शुरू होता है। बंद हो तो: जिन सवालों को ज़रूरत हो उन पर ही “Think” टैप करें।",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "नीचे वाला ही मॉडल, पर इसे पूरी किताब जितना संदर्भ एक साथ रखने की मेमोरी दी गई है। 48 GB की मशीन पर बची हुई RAM सटीकता से ज़्यादा संदर्भ पर बेहतर खर्च होती है — आप पूरा कॉन्ट्रैक्ट या साल भर के नोट्स दे दें तो भी यह सब नज़र में रखता है।",
  "The whole assistant, on your device": "पूरा असिस्टेंट, आपके डिवाइस पर",
