  "Nothing to do": "करने को कुछ नहीं",
  "When? Pick the date and time.": "कब? तारीख़ और समय चुनें।",
  "That time has already passed — pick a later one.": "वह समय निकल चुका है — बाद का कोई समय चुनें।",
  "That is more than a year away — check the date.": "यह एक साल से भी ज़्यादा दूर है — तारीख़ जाँच लें।",
  "Who should it go to?": "किसे जाना चाहिए?",
  "This doesn't look like something to set on the phone.": "यह फ़ोन पर सेट करने वाली चीज़ नहीं लगती।",
  "Could not open it": "इसे खोल नहीं सके",
  "No app on this phone can do that.": "इस फ़ोन पर कोई ऐप यह नहीं कर सकता।",
  "WhatsApp isn't installed — opened the share sheet instead.": "WhatsApp इंस्टॉल नहीं है — उसकी जगह शेयर शीट खोली गई।",
  "Unknown action": "अनजाना एक्शन",
