  "Wrote it (no tests).": "लिख दिया (कोई टेस्ट नहीं)।",
  "(no text on this page)": "(इस पेज पर कोई टेक्स्ट नहीं)",
  "Ask about this file…": "इस फ़ाइल के बारे में पूछें…",
