  "Explain page {n}": "पेज {n} समझाएँ",
  "I could not find anything about that in this document.": "इस डॉक्यूमेंट में मुझे इसके बारे में कुछ नहीं मिला।",
  "Looking through the pages…": "पेज देखे जा रहे हैं…",
