  "e.g. unpaid invoices over 50,000 · jobs this month by customer · top 5 cranes by revenue": "जैसे 50,000 से ज़्यादा के बकाया इनवॉइस · इस महीने के काम ग्राहक के हिसाब से · कमाई के हिसाब से टॉप 5 क्रेन",
