  "No forms yet. A form shows only the fields you need, in your order, with ready values — pick it when you add a record.": "अभी कोई फ़ॉर्म नहीं। फ़ॉर्म सिर्फ़ ज़रूरी फ़ील्ड दिखाता है, आपके क्रम में, तैयार वैल्यू के साथ — रिकॉर्ड जोड़ते समय इसे चुनें।",
