  "e.g. add Email and Tax ID to Suppliers, and a Warranty months field to Parts": "जैसे सप्लायर में ईमेल और टैक्स ID जोड़ो, और पार्ट्स में वारंटी के महीने वाला फ़ील्ड",
  "Saved — send this file; it opens in any browser, no Attune needed": "सेव हुआ — यह फ़ाइल भेजें; यह किसी भी ब्राउज़र में खुलती है, Attune की ज़रूरत नहीं",
  "Excel files need Python, which isn't in this build — use CSV.": "Excel फ़ाइलों के लिए Python चाहिए, जो इस बिल्ड में नहीं है — CSV इस्तेमाल करें।",
  "Making the Excel file…": "Excel फ़ाइल बन रही है…",
  "Couldn't make the Excel file: {e}": "Excel फ़ाइल नहीं बन सकी: {e}",
  "Give it to your team as an app: one file with all the data inside — it opens in any phone or computer browser, no Attune needed. When something needs changing, open the file here (Business → Open an app file), ask the AI, and send the new app back.": "इसे अपनी टीम को एक ऐप के रूप में दें: एक फ़ाइल जिसमें सारा डेटा है — यह किसी भी फ़ोन या कंप्यूटर के ब्राउज़र में खुलती है, Attune की ज़रूरत नहीं। कुछ बदलना हो तो फ़ाइल यहाँ खोलें (बिज़नेस → ऐप फ़ाइल खोलें), AI से कहें, और नया ऐप वापस भेज दें।",
  "Export as an app": "ऐप के रूप में एक्सपोर्ट करें",
  "Excel workbook (all tables)": "Excel वर्कबुक (सारी टेबल)",
  "The picture engine stopped before the picture was finished — Android may have closed it to free memory. Try “Quick draft”, or close other apps and try again.": "तस्वीर पूरी होने से पहले तस्वीर इंजन रुक गया — हो सकता है मेमोरी खाली करने के लिए Android ने उसे बंद कर दिया हो। “जल्दी का ड्राफ़्ट” आज़माएँ, या दूसरे ऐप बंद करके फिर कोशिश करें।",
  "The picture could not be made. Open Engine → Engine log and send me what it says.": "तस्वीर नहीं बन सकी। इंजन → इंजन लॉग खोलें और उसमें जो लिखा है वह मुझे भेजें।",
  "Multi-token prediction (faster writing)": "मल्टी-टोकन प्रेडिक्शन (तेज़ लिखना)",
  "Off by default: on some phones it doubles words and digits (“ItIt is is”, “20205”). Turn it on only if answers stay correct.": "डिफ़ॉल्ट रूप से बंद: कुछ फ़ोन पर यह शब्द और अंक दोहरा देता है (“ItIt is is”, “20205”)। इसे तभी चालू करें जब जवाब सही रहें।",
  "The last picture didn't finish:": "पिछली तस्वीर पूरी नहीं हुई:",
