  "fastest pictures": "सबसे तेज़ तस्वीरें",
  "a graphics card with 8 GB or more: the most capable model": "8 GB या ज़्यादा वाला ग्राफ़िक्स कार्ड: सबसे क़ाबिल मॉडल",
  "The most capable model: text inside pictures, busy scenes, people. Slow on a phone (about 10 minutes a picture), fast on a computer with a graphics card. Needs 12 GB RAM.": "सबसे क़ाबिल मॉडल: तस्वीरों के अंदर टेक्स्ट, भीड़ वाले दृश्य, लोग। फ़ोन पर धीमा (लगभग 10 मिनट एक तस्वीर), ग्राफ़िक्स कार्ड वाले कंप्यूटर पर तेज़। 12 GB RAM चाहिए।",
