  "Your free Pro trial: {n} days left — everything is unlocked. Keep it by choosing a plan.": "आपका फ़्री Pro ट्रायल: {n} दिन बाकी — सब कुछ खुला है। प्लान चुनकर इसे बनाए रखें।",
  "Free gives you {n} answers a day on every model. Pro removes every limit:": "फ़्री में हर मॉडल पर रोज़ {n} जवाब मिलते हैं। Pro हर सीमा हटा देता है:",
