  "Everything runs on your phone: no account, nothing uploaded. Your plan is checked on the phone, even offline.": "सब कुछ आपके फ़ोन पर चलता है: कोई अकाउंट नहीं, कुछ भी अपलोड नहीं। आपका प्लान फ़ोन पर ही जाँचा जाता है, ऑफ़लाइन भी।",
