  "Specificity → fewer misinterpretations": "सटीकता → कम गलतफ़हमियाँ",
  "Goal-framing beats tone adjectives alone": "लक्ष्य बताना सिर्फ़ लहजे के विशेषणों से बेहतर है",
  "Data first, question last improves grounding": "पहले डेटा, आख़िर में सवाल — इससे जवाब आधार पर टिका रहता है",
