  "Source-anchored prompts reduce invented detail": "स्रोत से बँधे प्रॉम्प्ट गढ़ी हुई बातें कम करते हैं",
  "Constraints up front prevent generic travel advice": "पहले से शर्तें बताने से आम यात्रा सलाह से बचते हैं",
  "Explaining the 'why' improves targeting (Anthropic)": "'क्यों' समझाने से निशाना बेहतर लगता है (Anthropic)",
  "Search tools need source + recency constraints": "सर्च टूल को स्रोत + ताज़गी की शर्तें चाहिए",
  "Constraints up front prevent generic answers": "पहले से शर्तें बताने से आम जवाबों से बचते हैं",
  "Active recall outperforms re-reading": "याद करके दोहराना फिर से पढ़ने से बेहतर है",
