  "Send log": "लॉग भेजें",
  "Log copied — paste it in the chat": "लॉग कॉपी हो गया — इसे चैट में पेस्ट करें",
  "Couldn't copy — press and hold the log to select it": "कॉपी नहीं हो सका — लॉग चुनने के लिए उसे दबाकर रखें",
  "Studio is drawing on the processor (slow). This phone has a graphics chip — try it: pictures and ×4 sharpening are many times faster there.": "Studio प्रोसेसर पर बना रहा है (धीमा)। इस फ़ोन में ग्राफ़िक्स चिप है — उसे आज़माएँ: वहाँ तस्वीरें और ×4 शार्पनिंग कई गुना तेज़ होती हैं।",
  "The next picture uses the graphics chip": "अगली तस्वीर ग्राफ़िक्स चिप इस्तेमाल करेगी",
  "This picture was drawn on the CPU because the graphics chip didn't finish; the next picture tries the graphics chip again.": "यह तस्वीर CPU पर बनी क्योंकि ग्राफ़िक्स चिप ने काम पूरा नहीं किया; अगली तस्वीर फिर से ग्राफ़िक्स चिप आज़माएगी।",
  "Drawing on the GPU failed twice, so Attune switched Studio to the CPU. ": "GPU पर बनाना दो बार फ़ेल हुआ, इसलिए Attune ने Studio को CPU पर कर दिया।",
  "The GPU driver stalled twice while loading the picture model, so Attune switched Studio to the CPU (you can try the GPU again below).": "तस्वीर वाला मॉडल लोड करते समय GPU ड्राइवर दो बार अटका, इसलिए Attune ने Studio को CPU पर कर दिया (आप नीचे GPU फिर से आज़मा सकते हैं)।",
  "Show only the models worth using on this device": "सिर्फ़ वे मॉडल दिखाएँ जो इस डिवाइस पर इस्तेमाल करने लायक हैं",
  "Combine your data": "अपना डेटा जोड़ें",
  "{t} › {f} holds {to} names ({m} of {n} found).": "{t} › {f} में {to} के नाम हैं ({n} में से {m} मिले)।",
  "Not in {to} yet: {x}": "अभी {to} में नहीं: {x}",
  "Link them": "इन्हें जोड़ें",
  "Linked: {t} › {f} → {to}": "जोड़ा गया: {t} › {f} → {to}",
  "{n} added to {to}": "{to} में {n} जोड़े गए",
  "When a column in one table names records of another (a job's customer, an invoice's crane), the phone finds it here and links them — no relationships to draw by hand.": "जब एक टेबल का कोई कॉलम दूसरी टेबल के रिकॉर्ड का नाम लेता है (काम का ग्राहक, इनवॉइस की क्रेन), तो फ़ोन उसे यहाँ ढूँढकर जोड़ देता है — हाथ से कोई रिश्ता बनाने की ज़रूरत नहीं।",
  "{t} with its linked tables": "{t} अपनी जुड़ी हुई टेबलों के साथ",
  "{n} records · with {l}": "{n} रिकॉर्ड · {l} के साथ",
  "Save as CSV": "CSV के रूप में सेव करें",
  "Merged into {t}: {u} updated, {n} new": "{t} में मिलाया गया: {u} अपडेट, {n} नए",
  "Merge into {t} (same {k} = same record)": "{t} में मिलाएँ (एक जैसा {k} = एक ही रिकॉर्ड)",
  "Add all to {t} as new": "सब {t} में नए के रूप में जोड़ें",
  "Start ×4": "×4 शुरू करें",
  "{n} figure(s) weren't in the sources, so they were left out.": "{n} आँकड़े स्रोतों में नहीं थे, इसलिए छोड़ दिए गए।",
  "×2 sharper · instant": "×2 ज़्यादा साफ़ · तुरंत",
  "×4 AI sharpen": "×4 AI शार्पनिंग",
  "Sharpening ×2…": "शार्पनिंग ×2…",
  "about {m} min left": "लगभग {m} मिनट बाकी",
  "Without the graphics chip, the ×4 AI sharpen takes about {m} minutes on this phone. “×2 sharper” takes a second. Start the ×4?": "ग्राफ़िक्स चिप के बिना इस फ़ोन पर ×4 AI शार्पनिंग में लगभग {m} मिनट लगते हैं। “×2 ज़्यादा साफ़” में एक सेकंड लगता है। ×4 शुरू करें?",
  "Highest resolution — sharpen every picture (×4 with the graphics chip; an instant ×2 without it)": "सबसे ऊँचा रेज़ोल्यूशन — हर तस्वीर शार्प करें (ग्राफ़िक्स चिप के साथ ×4; उसके बिना तुरंत ×2)",
  "The page was cut off — writing the rest…": "पेज बीच में कट गया — बाकी लिखा जा रहा है…",
  "🍽 Log it in Fit & Food": "🍽 Fit & Food में दर्ज करें",
  "e.g. Monthly report on our clinic: patients, waiting times, costs and what to fix next month": "जैसे हमारे क्लिनिक की मासिक रिपोर्ट: मरीज़, इंतज़ार का समय, लागत और अगले महीने क्या सुधारना है",
  "Who is it for? (optional) — e.g. investors, clients, my team": "यह किसके लिए है? (वैकल्पिक) — जैसे निवेशक, क्लाइंट, मेरी टीम",
