  "{n} figure(s) weren't in the sources, so they were left out of the charts.": "{n} आँकड़े स्रोतों में नहीं थे, इसलिए चार्ट से छोड़ दिए गए।",
  "{n} figure(s) on the slides weren't found in the sources — check them before presenting.": "स्लाइड पर {n} आँकड़े स्रोतों में नहीं मिले — प्रेज़ेंट करने से पहले उन्हें जाँच लें।",
  "{n} figure(s) came from the AI's memory — check them before presenting.": "{n} आँकड़े AI की याददाश्त से आए हैं — प्रेज़ेंट करने से पहले उन्हें जाँच लें।",
  "{n} figure(s) in the report weren't found in the sources — check them.": "रिपोर्ट में {n} आँकड़े स्रोतों में नहीं मिले — उन्हें जाँच लें।",
  "{n} figure(s) came from the AI's memory — check them before sending.": "{n} आँकड़े AI की याददाश्त से आए हैं — भेजने से पहले उन्हें जाँच लें।",
