  "The model took too long on this question — try a shorter one, or a faster model in Engine.": "इस सवाल पर मॉडल ने बहुत समय लिया — छोटा सवाल आज़माएँ, या इंजन में कोई तेज़ मॉडल।",
  "Reading your CV… the AI is sorting it into sections": "आपका CV पढ़ा जा रहा है… AI उसे हिस्सों में बाँट रहा है",
  "Imported — check each section and fix anything": "इंपोर्ट हो गया — हर हिस्सा जाँचें और जो ग़लत हो ठीक करें",
