  "not read: {f}": "नहीं पढ़ी गई: {f}",
  "From the phone's Notebook app: open a note (or select several) → Share → Attune → “Save to Shelf”. Or pick exported files here: text, Word, PDF, web pages, Google Keep, Evernote, a .zip, or photos of notes.": "फ़ोन के Notebook ऐप से: कोई नोट खोलें (या कई चुनें) → शेयर करें → Attune → “Shelf में सेव करें”। या यहाँ एक्सपोर्ट की हुई फ़ाइलें चुनें: टेक्स्ट, Word, PDF, वेब पेज, Google Keep, Evernote, .zip, या नोट्स की फ़ोटो।",
  "Versions & prices": "वर्शन और दाम",
  "Pros & cons": "फ़ायदे और नुकसान",
  "Compare with rivals": "प्रतिद्वंद्वियों से तुलना करें",
  "Latest news": "ताज़ा ख़बरें",
  "Those results were off-topic — searching another way…": "वे नतीजे विषय से हटकर थे — दूसरे तरीके से खोजा जा रहा है…",
  "Nothing found for that — try the area's name too (e.g. “… New Cairo”), or move the map there and search again.": "इसके लिए कुछ नहीं मिला — इलाके का नाम भी लिखकर देखें (जैसे “… New Cairo”), या मैप को वहाँ ले जाकर फिर से खोजें।",
  "from the map's centre": "मैप के बीच से",
  "saved place": "सेव की गई जगह",
  "Save this place": "यह जगह सेव करें",
  "This phone can't share its location with the app.": "यह फ़ोन ऐप के साथ अपनी लोकेशन शेयर नहीं कर सकता।",
  "Location is off for Attune — allow it in the phone's settings to see where you are.": "Attune के लिए लोकेशन बंद है — आप कहाँ हैं यह देखने के लिए फ़ोन की सेटिंग्स में इसकी अनुमति दें।",
  "Couldn't get your location — check that location is on.": "आपकी लोकेशन नहीं मिल सकी — जाँचें कि लोकेशन चालू है।",
  "“{n}” isn't kept on this phone any more — pick the file again.": "“{n}” अब इस फ़ोन पर नहीं रखी है — फ़ाइल फिर से चुनें।",
  "tap to continue": "जारी रखने के लिए टैप करें",
  "The text and your questions are kept on this phone only. Forget removes them.": "टेक्स्ट और आपके सवाल सिर्फ़ इसी फ़ोन पर रखे जाते हैं। भूल जाएँ दबाने से वे हट जाते हैं।",
  "Web · Auto": "वेब · ऑटो",
  "Web: Auto — it searches only when a question needs fresh facts": "वेब: ऑटो — यह तभी खोजता है जब किसी सवाल को ताज़ा जानकारी चाहिए",
  "Pick the best model for each question": "हर सवाल के लिए सबसे अच्छा मॉडल चुनें",
  "Reading your {f} conversation…": "आपकी {f} बातचीत पढ़ी जा रही है…",
  "Reading the conversation…": "बातचीत पढ़ी जा रही है…",
  "Shared links are opened in the Android app — or paste the conversation's text here.": "शेयर किए गए लिंक Android ऐप में खुलते हैं — या बातचीत का टेक्स्ट यहाँ पेस्ट करें।",
  "I read your conversation with {f}{t} (about {n} words). Ask me anything about it — check it, summarise it, or carry on from where it stopped.": "मैंने {f}{t} के साथ आपकी बातचीत पढ़ ली (लगभग {n} शब्द)। इसके बारे में कुछ भी पूछें — इसे जाँचें, इसका सारांश बनाएँ, या जहाँ रुकी थी वहीं से आगे बढ़ें।",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch it off with the Web button": "Attune · AI आपके डिवाइस पर चलता है · कोई अकाउंट नहीं, कोई साइन-इन नहीं · वेब पर खोज तभी जब सवाल को उसकी ज़रूरत हो (ऑटो) — वेब बटन से इसे बंद करें",
  "Web: Off — nothing is looked up": "वेब: बंद — कुछ भी नहीं खोजा जाता",
  "While Web is off in Chat, questions about prices, specs, news, scores or this year are still looked up (only the search words leave the phone). Off: nothing is looked up unless you turn Web on.": "चैट में वेब बंद होने पर भी दाम, स्पेसिफ़िकेशन, ख़बरें, स्कोर या इस साल से जुड़े सवाल खोजे जाते हैं (सिर्फ़ खोज के शब्द फ़ोन से बाहर जाते हैं)। बंद: जब तक आप वेब चालू न करें, कुछ भी नहीं खोजा जाता।",
  "The model wrote nonsense — restarting it in safe mode and asking again…": "मॉडल ने बेतुकी बातें लिखीं — उसे सेफ़ मोड में फिर से शुरू करके दोबारा पूछा जा रहा है…",
  "This model writes nonsense on this phone, even in safe mode. Pick another model in Engine (Core works well) and tell us which one failed.": "यह मॉडल इस फ़ोन पर सेफ़ मोड में भी बेतुकी बातें लिखता है। इंजन में कोई दूसरा मॉडल चुनें (Core अच्छा चलता है) और हमें बताएँ कि कौन-सा फ़ेल हुआ।",
  "Safe mode is on for this model: it once wrote nonsense on this phone, so it runs without speed tricks and with full-precision memory (a little slower, same answers).": "इस मॉडल के लिए सेफ़ मोड चालू है: इसने एक बार इस फ़ोन पर बेतुकी बातें लिखी थीं, इसलिए यह बिना रफ़्तार वाली तरकीबों के और पूरी प्रिसिज़न वाली मेमोरी के साथ चलता है (थोड़ा धीमा, जवाब वही)।",
  "Turn safe mode off": "सेफ़ मोड बंद करें",
  "Or any topic you like": "या कोई भी विषय जो आप चाहें",
  "I can answer about your next period, being late, ovulation, the fertile window, cycle and period length, your history and symptoms.": "मैं आपके अगले पीरियड, देरी, ओव्यूलेशन, फ़र्टाइल विंडो, साइकिल और पीरियड की लंबाई, आपकी हिस्ट्री और लक्षणों के बारे में जवाब दे सकता हूँ।",
