  "Visa required for most nationalities.": "ज़्यादातर राष्ट्रीयताओं के लिए वीज़ा ज़रूरी।",
  "Visa required. The e-Visa route needs a valid US, Canadian, Australian, UK, Schengen or Japanese visa.": "वीज़ा ज़रूरी। e-Visa के लिए वैध US, कनाडा, ऑस्ट्रेलिया, UK, Schengen या जापानी वीज़ा चाहिए।",
