  "e-Visa online, 90 days. There is no reliable visa on arrival — apply before flying.": "ऑनलाइन e-Visa, 90 दिन। भरोसेमंद वीज़ा ऑन अराइवल नहीं है — उड़ान से पहले आवेदन करें।",
