  "Android does this for apps installed from a file instead of Google Play. In App info tap ⋮ (top right) → Allow restricted settings, then turn Attune on here again.": "Google Play की जगह फ़ाइल से इंस्टॉल किए ऐप्स के साथ Android ऐसा करता है। App info में ⋮ (ऊपर दाईं ओर) → Allow restricted settings टैप करें, फिर यहाँ Attune को दोबारा चालू करें।",
  "Open App info": "App info खोलें",
