  "Running on the NPU ({d}).": "NPU पर चल रहा है ({d})।",
  "Runs the model on the Snapdragon NPU (Hexagon): much cooler, often faster at reading. Works best with Core Max (8-bit). Switches itself back to the CPU if anything goes wrong.": "मॉडल को Snapdragon NPU (Hexagon) पर चलाता है: फ़ोन काफ़ी ठंडा, पढ़ने में अक्सर तेज़। Core Max (8-bit) के साथ सबसे अच्छा। कुछ गड़बड़ हो तो अपने आप CPU पर लौट आता है।",
  "This phone's NPU could not be used by the engine — Attune stays on the CPU.": "इंजन इस फ़ोन का NPU इस्तेमाल नहीं कर सका — Attune CPU पर ही रहेगा।",
  "Last time, starting on the NPU closed the app. Attune is back on the CPU; you can try it again in Engine → Speed.": "पिछली बार NPU पर शुरू करते ही ऐप बंद हो गया था। Attune वापस CPU पर है; आप इंजन → स्पीड में फिर आज़मा सकते हैं।",
  "You have {b}. Until {d} ({n} days) these are due: {t}. What is left, shared over the days, is what you can spend each day.": "आपके पास {b} है। {d} ({n} दिन) तक ये देय हैं: {t}। जो बचता है, उसे दिनों में बाँटकर, उतना आप हर दिन खर्च कर सकते हैं।",
  "Nothing due before then.": "तब तक कुछ देय नहीं।",
  "Tip: add your salary as a repeating income in Money, and this counts until payday.": "टिप: पैसे में अपनी सैलरी को दोहराने वाली आमदनी के रूप में जोड़ें, तो यह सैलरी के दिन तक गिनेगा।",
  "Keep aside": "अलग रखें",
