  "Safe to spend today": "आज का सुरक्षित खर्च",
  "In today's money": "आज के पैसे में",
  "Installments are cheaper in real money by {x}: keep the cash in the bank and pay monthly from it.": "असली पैसे में किस्तें {x} सस्ती हैं: कैश बैंक में रखें और हर महीने उसी से भरें।",
  "Cash is cheaper in real money by {x}, even after what the bank would pay you.": "असली पैसे में कैश {x} सस्ता है, बैंक के ब्याज के बाद भी।",
  "Cash and installments cost about the same in real money.": "असली पैसे में कैश और किस्तें लगभग बराबर हैं।",
