  "Mission started — Attune works on it every day": "मिशन शुरू — Attune इस पर रोज़ काम करता है",
  "Say a goal with a deadline. Attune works on it every day: it reads your money, food and Scout ads, gives your real chance, and the one step for today.": "डेडलाइन के साथ कोई लक्ष्य बोलें। Attune इस पर रोज़ काम करता है: आपके पैसे, खाना और Scout ऐड पढ़ता है, आपकी असली संभावना और आज का एक कदम बताता है।",
  "e.g. «عايز أوفر 60 ألف قبل يونيو»": "जैसे «عايز أوفر 60 ألف قبل يونيو»",
  "Save {t}": "{t} बचाएँ",
  "Lose {t} kg": "{t} kg घटाएँ",
