  "by {d}": "{d} तक",
  "add a date (e.g. by June)": "तारीख जोड़ें (जैसे जून तक)",
  "Say a number and a date: save 60,000 by June · lose 6 kg before 20 January · buy … under 900k by 1 December · spend no more than 3,000 on food this month · pay off Ahmed's debt by December · finish the Turkish course by December.": "एक संख्या और तारीख बोलें: जून तक 60,000 बचाओ · 20 जनवरी से पहले 6 kg घटाओ · 1 दिसंबर तक … 900k से कम में खरीदो · इस महीने खाने पर 3,000 से ज़्यादा खर्च नहीं · दिसंबर तक अहमद का कर्ज़ चुकाओ · दिसंबर तक तुर्की कोर्स पूरा करो।",
  "Start the mission": "मिशन शुरू करें",
  "Your money missions need {a} a month together, but you keep about {b}. Pause one, or move a date.": "आपके पैसे वाले मिशनों को मिलाकर हर महीने {a} चाहिए, पर आप लगभग {b} बचाते हैं। एक रोकें, या कोई तारीख आगे करें।",
  "No missions yet. Start one above — a saving goal, a weight goal, something to buy, a spending limit, a debt or a course.": "अभी कोई मिशन नहीं। ऊपर से शुरू करें — बचत का लक्ष्य, वज़न का लक्ष्य, कुछ खरीदना, खर्च की सीमा, कोई कर्ज़ या कोर्स।",
  "A goal with a date — Attune works on it every day": "तारीख वाला लक्ष्य — Attune इस पर रोज़ काम करता है",
  "{c}% chance": "{c}% संभावना",
  "A goal with a date — Attune works on it every day and shows your real chance": "तारीख वाला लक्ष्य — Attune इस पर रोज़ काम करता है और आपकी असली संभावना दिखाता है",
  "Where": "कहाँ",
  "Every tool in three steps, with a drawing of its screen — and a plan to make Attune part of your day.": "हर टूल तीन कदमों में, उसकी स्क्रीन की ड्रॉइंग के साथ — और Attune को अपने दिन का हिस्सा बनाने का प्लान।",
  "Sync": "सिंक",
  "Backup & sync": "बैकअप और सिंक",
  "Synced — {a} new, {c} updated. Reopening…": "सिंक हो गया — {a} नए, {c} अपडेट। फिर से खुल रहा है…",
  "Waiting for the other device…": "दूसरे डिवाइस का इंतज़ार…",
  "Merging…": "मिला रहा है…",
  "Locking and sending…": "लॉक करके भेज रहा है…",
  "Signing in to Google…": "Google में साइन इन कर रहा है…",
  "Locking and uploading…": "लॉक करके अपलोड कर रहा है…",
  "Type the address shown on the other device, like 192.168.1.20:41873": "दूसरे डिवाइस पर दिखा पता लिखें, जैसे 192.168.1.20:41873",
  "The code has 8 letters and numbers": "कोड में 8 अक्षर और अंक हैं",
  "Set your sync passphrase first — the same on every device.": "पहले अपना सिंक पासफ़्रेज़ सेट करें — हर डिवाइस पर एक जैसा।",
  "Keep your phone and computer (or two phones) the same. The data is locked before it leaves this device; what you delete on one is deleted on the other, nothing else is lost.": "अपना फ़ोन और कंप्यूटर (या दो फ़ोन) एक जैसे रखें। डेटा इस डिवाइस से निकलने से पहले लॉक होता है; एक पर जो डिलीट करें वह दूसरे पर भी डिलीट होता है, और कुछ नहीं खोता।",
  "Wi-Fi": "Wi-Fi",
  "Google Drive": "Google Drive",
  "Allow Attune to find your other device on this Wi-Fi (Android asks once).": "Attune को इस Wi-Fi पर आपका दूसरा डिवाइस ढूँढने दें (Android एक बार पूछता है)।",
  "On the other device: Backup → Sync → Wi-Fi → Connect, and type:": "दूसरे डिवाइस पर: बैकअप → सिंक → Wi-Fi → कनेक्ट, और लिखें:",
  "not on Wi-Fi": "Wi-Fi पर नहीं",
  "Show a code on this device": "इस डिवाइस पर कोड दिखाएँ",
  "Or connect to the other device": "या दूसरे डिवाइस से कनेक्ट करें",
  "Make this device exactly like the other one (removes what the other doesn't have)": "इस डिवाइस को बिल्कुल दूसरे जैसा बनाएँ (जो दूसरे में नहीं है उसे हटा देता है)",
  "Connect and sync": "कनेक्ट करके सिंक करें",
  "One file in your own Google Drive, in a hidden folder only Attune can open. It is locked with your sync passphrase on this device, so Google only stores noise.": "आपकी अपनी Google Drive में एक फ़ाइल, एक छिपे फ़ोल्डर में जिसे सिर्फ़ Attune खोल सकता है। यह इस डिवाइस पर आपके सिंक पासफ़्रेज़ से लॉक होती है, इसलिए Google के पास सिर्फ़ बेमतलब डेटा रहता है।",
  "Sync passphrase set on this device.": "इस डिवाइस पर सिंक पासफ़्रेज़ सेट हो गया।",
  "Sync passphrase (10+ characters, the same on every device)": "सिंक पासफ़्रेज़ (10+ अक्षर, हर डिवाइस पर एक जैसा)",
  "Save passphrase": "पासफ़्रेज़ सेव करें",
  "Sync with Google Drive": "Google Drive से सिंक करें",
  "Last synced: {d}": "आखिरी सिंक: {d}",
  "Wrong code or passphrase — nothing was changed.": "गलत कोड या पासफ़्रेज़ — कुछ नहीं बदला।",
  "Use at least 10 characters — the file lives in your Drive, so the passphrase is its only lock.": "कम से कम 10 अक्षर रखें — फ़ाइल आपकी Drive में है, इसलिए पासफ़्रेज़ ही उसका अकेला ताला है।",
  "That passphrase is too easy to guess.": "यह पासफ़्रेज़ बहुत आसानी से अंदाज़ा लगाया जा सकता है।",
  "Only available in the Attune app": "सिर्फ़ Attune ऐप में उपलब्ध",
  "Google sync on the computer comes in the next update — use Wi-Fi with your phone for now.": "कंप्यूटर पर Google सिंक अगले अपडेट में आएगा — अभी अपने फ़ोन के साथ Wi-Fi इस्तेमाल करें।",
  "Remember your notes": "अपने नोट्स याद रखें",
