  "Save this part": "यह हिस्सा सेव करें",
  "Copied as it is, no re-encoding: quick and cool. The part starts at the nearest key frame, so it may begin a second early.": "जैसा है वैसा कॉपी, बिना री-एन्कोडिंग: तेज़ और फ़ोन ठंडा। हिस्सा सबसे पास के की-फ़्रेम से शुरू होता है, इसलिए एक सेकंड पहले शुरू हो सकता है।",
  "Write the times like 1:20 or 0:45": "समय ऐसे लिखें: 1:20 या 0:45",
  "The end must come after the start": "अंत शुरुआत के बाद होना चाहिए",
  "This video has no sound": "इस वीडियो में आवाज़ नहीं है",
