  "Tap 👎 on an answer in a chat with this assistant and write the right one — it becomes a rule here.": "इस असिस्टेंट वाली चैट में किसी जवाब पर 👎 टैप करें और सही जवाब लिखें — वह यहाँ नियम बन जाएगा।",
