  "Your watch's temperature rose {r} °C: ovulation around {o}, so the period is expected {n}.": "आपकी वॉच का तापमान {r} °C बढ़ा: ओव्यूलेशन लगभग {o}, इसलिए पीरियड {n} आने की उम्मीद है।",
