  "No temperature rise yet — ovulation looks later than usual, so the period will likely be later than the date above.": "अभी तापमान नहीं बढ़ा — ओव्यूलेशन आम से देर लग रहा है, इसलिए पीरियड शायद ऊपर की तारीख से देर से आएगा।",
