  "One page {c} can open on any phone: what they owe, their invoices, payments and job orders. No costs, no other client. Send it on WhatsApp or by email.": "एक पेज जिसे {c} किसी भी फ़ोन पर खोल सकता है: उन पर कितना बकाया है, उनके इनवॉइस, भुगतान और जॉब ऑर्डर। कोई लागत नहीं, कोई दूसरा क्लाइंट नहीं। इसे WhatsApp या ईमेल से भेजें।",
