  "Your phone's own offline speech recogniser listens to the video, piece by piece — the sound never leaves the phone. About as long as the video.": "आपके फ़ोन का अपना ऑफ़लाइन स्पीच रिकग्नाइज़र वीडियो को थोड़ा-थोड़ा करके सुनता है — आवाज़ कभी फ़ोन से बाहर नहीं जाती। इसमें लगभग वीडियो जितना ही समय लगता है।",
  "Subtitles need Android 13 or newer": "सबटाइटल के लिए Android 13 या उससे नया वर्ज़न चाहिए",
  "Google sync on the computer needs one setup step by Attune's owner (its Google client) — use Wi-Fi with your phone until then.": "कंप्यूटर पर Google सिंक के लिए Attune के मालिक (उसके Google क्लाइंट) द्वारा एक सेटअप स्टेप ज़रूरी है — तब तक अपने फ़ोन के साथ Wi-Fi का इस्तेमाल करें।",
  "The first time, Google's sign-in page opens in your browser; after that the computer stays signed in.": "पहली बार आपके ब्राउज़र में Google का साइन-इन पेज खुलेगा; उसके बाद कंप्यूटर साइन-इन रहेगा।",
  "Built from the \"{k}\" template in a second — change anything you like": "एक सेकंड में \"{k}\" टेम्पलेट से तैयार — जो चाहें बदलें",
  "Android is downloading the offline speech pack for this language — try again when it finishes": "Android इस भाषा के लिए ऑफ़लाइन स्पीच पैक डाउनलोड कर रहा है — पूरा होने पर फिर कोशिश करें",
  "That language isn't installed for offline voice — add it in the phone's Settings → Google → Speech → Offline languages": "ऑफ़लाइन आवाज़ के लिए वह भाषा इंस्टॉल नहीं है — इसे फ़ोन की सेटिंग्स → Google → स्पीच → ऑफ़लाइन भाषाएँ में जोड़ें",
