  "The phone listens for «يا أتيون» or “Hey Attune” and opens this screen. On this phone only — nothing is recorded or sent. A notification shows while it listens.": "फ़ोन «يا أتيون» या “Hey Attune” सुनता है और यह स्क्रीन खोल देता है। सिर्फ़ इसी फ़ोन पर — कुछ भी रिकॉर्ड या भेजा नहीं जाता। सुनते समय एक नोटिफिकेशन दिखता है।",
  "Allow the microphone to use it.": "इसके इस्तेमाल के लिए माइक्रोफ़ोन की अनुमति दें।",
  "When": "कब",
