  "Done — now it wakes for your voice.": "हो गया — अब यह आपकी आवाज़ पर जागेगा।",
  "Didn't hear it clearly — try again a bit closer to the phone.": "साफ़ सुनाई नहीं दिया — फ़ोन के थोड़ा करीब आकर फिर कोशिश करें।",
  "Your voice": "आपकी आवाज़",
  "Only a voice like yours wakes it (fewer false wakes).": "सिर्फ़ आपकी जैसी आवाज़ से यह जागता है (गलती से चालू होना कम होता है)।",
  "Say «يا أتيون» 3 times so it wakes for you, not the TV or people around you.": "3 बार «يا أتيون» कहें ताकि यह सिर्फ़ आपकी आवाज़ पर जागे, टीवी या आस-पास के लोगों की आवाज़ पर नहीं।",
