  "Forget my voice": "मेरी आवाज़ भूल जाएँ",
  "Forgotten — any voice wakes it now.": "भूल गया — अब यह किसी भी आवाज़ पर जाग जाएगा।",
  "Talk to Attune": "Attune से बात करें",
  "Your details — bookings and better answers": "आपका विवरण — बुकिंग और बेहतर जवाब",
  "Private: everything here stays on this phone — Attune never uploads it, and its AI runs on the phone. Answers and agents use only your trip and daily-life details (never your passport, phone or email). A booking site gets your name, passport and phone only when you tap “Fill my details”.": "निजी: यहाँ सब कुछ इसी फ़ोन पर रहता है — Attune इसे कभी अपलोड नहीं करता, और इसका AI फ़ोन पर ही चलता है। जवाब और एजेंट सिर्फ़ आपकी यात्रा और रोज़मर्रा की जानकारी का इस्तेमाल करते हैं (आपका पासपोर्ट, फ़ोन या ईमेल कभी नहीं)। किसी बुकिंग साइट को आपका नाम, पासपोर्ट और फ़ोन तभी मिलता है जब आप “मेरा विवरण भरें” पर टैप करते हैं।",
  "Use my details to make answers and agents fit me": "जवाबों और एजेंटों को मेरे अनुकूल बनाने के लिए मेरे विवरण का इस्तेमाल करें",
  "Trips and hotels": "यात्राएँ और होटल",
  "Agents use these when your sentence doesn't say — e.g. a hotel watch looks for your stars by itself.": "जब आपके वाक्य में यह न लिखा हो तो एजेंट इनका इस्तेमाल करते हैं — जैसे होटल खोजने वाला एजेंट अपने-आप आपकी पसंद के स्टार देखता है।",
  "Daily life": "रोज़मर्रा की ज़िंदगी",
  "So Chat's answers fit you: food, health, your car, your work.": "ताकि चैट के जवाब आपके अनुकूल हों: खाना, सेहत, आपकी कार, आपका काम।",
  "For booking forms": "बुकिंग फ़ॉर्म के लिए",
  "Typed into a booking site only when you tap “Fill my details”. Never used in answers.": "किसी बुकिंग साइट में तभी भरा जाता है जब आप “मेरा विवरण भरें” पर टैप करते हैं। जवाबों में कभी इस्तेमाल नहीं होता।",
