  "Open Projects: one folder per job — its files, its chats and what Attune made for it.": "प्रोजेक्ट खोलें: हर काम का एक फ़ोल्डर — उसकी फ़ाइलें, चैट और जो Attune ने उसके लिए बनाया।",
  "Drop a PDF into Ask a PDF and ask it anything — the answer shows the page.": "PDF से पूछें में PDF डालें और कुछ भी पूछें — जवाब में पेज बताया जाता है।",
  "Turn your notes into slides or a report in one sentence.": "अपने नोट्स को एक वाक्य में स्लाइड या रिपोर्ट बनाएँ।",
  "Keep every job in its own project — the next question about it is answered from its own files.": "हर काम को उसके अपने प्रोजेक्ट में रखें — अगला सवाल उसकी अपनी फ़ाइलों से जवाब पाता है।",
  "Give me a short plan to learn {t}, step by step, with free resources.": "{t} सीखने का एक छोटा प्लान दो, कदम-दर-कदम, मुफ़्त संसाधनों के साथ।",
  "Directions to {p} — in Google Maps": "{p} तक का रास्ता — Google Maps में",
  "Download the area in Google Maps once, and the directions work without internet too.": "इलाका एक बार Google Maps में डाउनलोड कर लें, फिर रास्ता बिना इंटरनेट भी चलेगा।",
  "≈ {p} a month — save {n}%": "≈ {p} प्रति माह — {n}% बचत",
  "Cheapest now: {p} ({d})": "अभी सबसे सस्ता: {p} ({d})",
  "{n} nights between {a} and {b}": "{a} और {b} के बीच {n} रातें",
