  "or": "या",
  "within 1 km": "1 km के दायरे में",
  "{n} start days checked": "शुरुआत के {n} दिन जाँचे गए",
  "Photo received — ask anything about it (a receipt? say “add to Money”)": "फ़ोटो मिल गई — इसके बारे में कुछ भी पूछें (रसीद है? कहें “पैसे में जोड़ें”)",
  "Your selected text is in the chat box — say what to do with it": "आपका चुना गया टेक्स्ट चैट बॉक्स में है — बताएँ इसके साथ क्या करना है",
  "No price shown — open the ad": "कोई कीमत नहीं दिखी — विज्ञापन खोलें",
  "Everything you must pay, collect, remember or watch — on one list.": "हर वह चीज़ जिसका आपको भुगतान करना है, वसूलना है, याद रखना है या निगरानी करनी है — एक ही सूची में।",
  "Add anything — “Ahmed owes me 12,000, 1,000 a month”": "कुछ भी जोड़ें — “Ahmed पर मेरे 12,000 बाकी हैं, 1,000 हर महीने”",
  "I couldn't read that — try: “Ahmed owes me 12,000, 1,000 a month” or “remind me Sunday at 5 to call the client”": "मैं वह समझ नहीं पाया — ऐसे लिखें: “Ahmed पर मेरे 12,000 बाकी हैं, 1,000 हर महीने” या “रविवार को 5 बजे क्लाइंट को कॉल करने की याद दिलाएँ”",
  "Marked as paid": "भुगतान किया गया के रूप में चिह्नित",
