  "One shopping list, who paid what for the house, and reminders for your parents — shared with your family's phones only, locked with a family code. No account, no server.": "खरीदारी की एक सूची, घर के लिए किसने क्या खर्च किया, और आपके माता-पिता के लिए रिमाइंडर — सिर्फ़ आपके परिवार के फ़ोनों के साथ साझा, फ़ैमिली कोड से सुरक्षित। कोई अकाउंट नहीं, कोई सर्वर नहीं।",
