  "Pick a family code of 6 letters or more first": "पहले 6 या उससे ज़्यादा अक्षरों का फ़ैमिली कोड चुनें",
  "Our family list in Attune — open it in Attune with our family code.": "Attune में हमारे परिवार की सूची — इसे हमारे फ़ैमिली कोड के साथ Attune में खोलें।",
