  "Add the family below (a reminder for someone adds them too), or open a family file from their phone.": "नीचे परिवार के सदस्यों को जोड़ें (किसी के लिए रिमाइंडर बनाने से भी वे जुड़ जाते हैं), या उनके फ़ोन से परिवार की फ़ाइल खोलें।",
  "Reminders for the family": "परिवार के लिए रिमाइंडर",
