  "Share with the family": "परिवार के साथ शेयर करें",
  "The list, the house money and the reminders — nothing else — locked with your family code. Send the file (WhatsApp, anything); on their phone: Family → Open a family file. Each phone keeps both sides.": "सूची, घर का खर्च और रिमाइंडर — इसके अलावा कुछ नहीं — आपके फ़ैमिली कोड से लॉक। फ़ाइल भेजें (WhatsApp या कहीं भी); उनके फ़ोन पर: परिवार → परिवार की फ़ाइल खोलें। हर फ़ोन दोनों तरफ़ का हिसाब रखता है।",
  "Family code (the same on every phone)": "फ़ैमिली कोड (हर फ़ोन पर एक जैसा)",
