  "Write it like you'd say it — “salary 25,000 on the 1st”. Attune then shows how much you can spend each day and keeps your bills aside.": "जैसे आप बोलते हैं वैसे लिखें — “1 तारीख को सैलरी 25,000”। फिर Attune दिखाता है कि आप हर दिन कितना खर्च कर सकते हैं और आपके बिलों के पैसे अलग रख देता है।",
  "Add my income": "मेरी आमदनी जोड़ें",
