  "Grey = what happened. The rest is the plan — tap any cell to type your own number, like Excel.": "स्लेटी = जो हो चुका है। बाकी प्लान है — Excel की तरह अपनी संख्या लिखने के लिए किसी भी सेल पर टैप करें।",
