  "This page didn't load — check the internet, or tap Done.": "यह पेज लोड नहीं हुआ — इंटरनेट जाँचें, या ‘हो गया’ पर टैप करें।",
  "No Buy now button here — tap it yourself, I'll fill your details on the next pages.": "यहाँ ‘अभी खरीदें’ बटन नहीं मिला — उस पर खुद टैप करें, अगले पेजों पर मैं आपका विवरण भर दूँगा।",
  "Pressed “{b}” — check the order; the payment is yours.": "“{b}” दबाया गया — ऑर्डर जाँच लें; भुगतान आपको करना है।",
  "Couldn't see that exact product yet — I'll keep looking.": "वह सटीक प्रोडक्ट अभी नहीं दिखा — मैं तलाश जारी रखूँगा।",
  "Taken to checkout — your details are filled; you pay there. Tap Done here once ordered.": "चेकआउट पर ले जाया गया — आपका विवरण भर दिया गया है; आप वहाँ भुगतान करें। ऑर्डर हो जाने पर यहाँ ‘हो गया’ पर टैप करें।",
  "Not finished — tap Order it again whenever you want.": "पूरा नहीं हुआ — जब चाहें ‘इसे ऑर्डर करें’ पर फिर से टैप करें।",
