  "Add today's gold price in Zakāt settings first — the niṣāb comes from it.": "पहले ज़कात सेटिंग्स में आज के सोने की कीमत जोड़ें — निसाब उसी से निकलता है।",
  "Below the niṣāb — nothing is due": "निसाब से कम — कोई ज़कात वाजिब नहीं है",
  "{n} more to reach it": "इस तक पहुँचने के लिए {n} और",
  "The rulings are the ledger's Zakāt engine's, unchanged.": "नियम बही-खाते के ज़कात इंजन के ही हैं, बिना किसी बदलाव के।",
  "1 · Today's gold price": "1 · आज के सोने की कीमत",
  "Pick your country once — the price follows it and updates by itself twice a day.": "एक बार अपना देश चुनें — कीमत उसी के अनुसार आती है और दिन में दो बार अपने-आप अपडेट होती है।",
  "1 g of 24k gold": "24k सोने का 1 g",
  "2 · Your school": "2 · आपका मसलक (मज़हब)",
  "Choosing it sets the niṣāb and worn jewellery the way that school does. You can still change each one.": "इसे चुनने से निसाब और पहनने वाले गहनों का नियम उस मसलक के अनुसार सेट हो जाता है। आप फिर भी हर एक को बदल सकते हैं।",
  "3 · Gold and silver you own": "3 · आपके पास मौजूद सोना और चाँदी",
  "Put 0 or leave empty what you don't have.": "जो आपके पास नहीं है उसमें 0 लिखें या खाली छोड़ दें।",
  "4 · Your Zakāt year": "4 · आपका ज़कात वर्ष",
  "The day your money first reached the niṣāb (the ḥawl). Zakāt is due one lunar year after it.": "वह दिन जब आपका पैसा पहली बार निसाब तक पहुँचा (हौल)। उसके एक चंद्र वर्ष बाद ज़कात वाजिब होती है।",
  "5 · Money and debts": "5 · पैसे और कर्ज़",
