  "Salary, bills and People & plans come from Money by themselves. Red = a month that runs short. Tap a month to change it.": "सैलरी, बिल और लोग और प्लान अपने-आप पैसे से आते हैं। लाल = वह महीना जिसमें पैसे कम पड़ रहे हैं। बदलने के लिए किसी महीने पर टैप करें।",
