  "You already have {n} — add what tells them apart (plumber, work…), and Attune will ask which one when it isn't clear.": "आपके पास पहले से {n} है — पहचान के लिए कुछ जोड़ें (प्लंबर, काम…), और जब स्पष्ट न हो तो Attune पूछ लेगा कि कौन-सा।",
