  "Everything about {n}": "{n} के बारे में सब कुछ",
  "Nothing linked yet. When you write {n} (or another name of theirs) in Money, a note or a message, it shows here.": "अभी कुछ नहीं जुड़ा है। जब आप पैसे, किसी नोट या मैसेज में {n} (या उनका कोई दूसरा नाम) लिखते हैं, तो वह यहाँ दिखता है।",
  "The people, places and things in your life. Attune links everything about each one — payments, notes, messages, follow-ups — and Chat answers from it. Two with the same name? It asks which one.": "आपकी ज़िंदगी के लोग, जगहें और चीज़ें। Attune हर एक से जुड़ी सारी बातें — भुगतान, नोट्स, मैसेज, फ़ॉलो-अप — एक साथ जोड़ता है और चैट उसी से जवाब देता है। एक ही नाम के दो लोग हैं? यह पूछ लेता है कि कौन-सा।",
