  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \\\"nothing leaves this phone\\\".": "मॉडल खुद कभी नेटवर्क का इस्तेमाल नहीं करता। यह लॉग ऐप द्वारा बनाए या अस्वीकार किए गए हर कनेक्शन, होस्ट और कारण की सूची दिखाता है — जो \"इस फ़ोन से कुछ भी बाहर नहीं जाता\" का प्रमाण है।",
