  "Which exact model and year is it most likely? Say which clues you used and how sure you are.": "यह सबसे अधिक संभावना से कौन-सा सटीक मॉडल और साल है? बताएँ कि आपने किन संकेतों का इस्तेमाल किया और आप कितने निश्चित हैं।",
  "Give its main specifications in a table.": "एक टेबल में इसके मुख्य स्पेसिफ़िकेशन दें।",
  "For my use, which one should I choose and why?": "मेरे उपयोग के लिए मुझे कौन-सा चुनना चाहिए और क्यों?",
