  "Turn these steps into a short checklist I can tick.": "इन चरणों को एक छोटी चेकलिस्ट में बदलें जिस पर मैं टिक लगा सकूँ।",
  "Give me a real-world example with numbers.": "मुझे संख्याओं के साथ एक वास्तविक उदाहरण दें।",
  "Explain that simply, as if I have no background.": "इसे सरल भाषा में समझाएँ, मानो मुझे इसकी कोई जानकारी न हो।",
  "Make it more formal.": "इसे अधिक औपचारिक बनाएँ।",
  "Make it shorter.": "इसे छोटा करें।",
  "Tell me more about the first option.": "मुझे पहले विकल्प के बारे में और बताएँ।",
  "Turn the plan into a checklist.": "प्लान को एक चेकलिस्ट में बदलें।",
  "Translate it back so I can check the meaning.": "इसका वापस अनुवाद करें ताकि मैं मतलब जाँच सकूँ।",
