  "Translate it": "इसका अनुवाद करें",
  "Make it sound like me": "इसे मेरे लिखने के अंदाज़ जैसा बनाएँ",
  "Convert the file": "फ़ाइल कन्वर्ट करें",
  "Keep it in Mind": "इसे Mind में रखें",
  "Find what I kept": "जो मैंने सेव किया था उसे ढूँढें",
  "Make an automation": "ऑटोमेशन बनाएँ",
