  "Start a mission": "कोई मिशन शुरू करें",
  "Give it to an agent (find, watch, order)": "इसे किसी एजेंट को दें (ढूँढें, नज़र रखें, ऑर्डर करें)",
  "Save it as a note": "इसे नोट के रूप में सेव करें",
  "the start and end dates": "शुरू और समाप्त होने की तारीखें",
  "the rent and when it is paid": "किराया और उसका भुगतान कब किया जाता है",
