  "Read the offer again with this": "इसके साथ ऑफ़र को फिर से पढ़ें",
  "They want money before you see or receive it.": "सामान देखने या मिलने से पहले ही वे पैसे माँग रहे हैं।",
  "Payment to a personal wallet or gift card — very hard to get back.": "किसी निजी वॉलेट या गिफ़्ट कार्ड में भुगतान — इसे वापस पाना बहुत मुश्किल होता है।",
  "They ask for a code sent to your phone — that is how accounts and wallets are stolen.": "वे आपके फ़ोन पर आया कोड माँग रहे हैं — इसी तरह अकाउंट और वॉलेट चोरी होते हैं।",
