  "Guaranteed high profit — the sign of a Ponzi / investment scam.": "पक्के भारी मुनाफ़े का वादा — यह पोंज़ी / निवेश धोखाधड़ी की निशानी है।",
  "No warranty or returns.": "कोई वारंटी या वापसी नहीं।",
  "It says copy / replica — not the original product.": "इसमें कॉपी / रेप्लिका लिखा है — यह असली प्रोडक्ट नहीं है।",
  "No real brand is named.": "किसी असली ब्रांड का नाम नहीं दिया गया है।",
  "Says 0% interest — the real cost is checked below.": "0% ब्याज लिखा है — असली लागत की जाँच नीचे की गई है।",
  "A seller with no ratings.": "बिना किसी रेटिंग वाला विक्रेता।",
  "The installments add nothing over the cash price — a real 0%.": "किस्तों का कुल योग नकद कीमत से ज़्यादा नहीं है — यह वाकई 0% ब्याज है।",
  "Can I see it and pay on delivery (cash / card on receipt)?": "क्या मैं इसे देख सकता/सकती हूँ और मिलने पर भुगतान (डिलीवरी पर नकद / कार्ड) कर सकता/सकती हूँ?",
  "What is the exact brand and model number? Can you send a photo of the label?": "सटीक ब्रांड और मॉडल नंबर क्या है? क्या आप लेबल की फ़ोटो भेज सकते हैं?",
  "Is there an official warranty, and for how long? Invoice included?": "क्या इसकी आधिकारिक वारंटी है, और कितने समय की? क्या इनवॉइस मिलेगा?",
  "Can you do a better price? Others sell it for less.": "क्या आप कीमत थोड़ी कम कर सकते हैं? दूसरे इसे कम दाम में बेच रहे हैं।",
  "What is the total I pay, all fees included? Is there an early-payment penalty?": "सभी शुल्क मिलाकर मुझे कुल कितना भुगतान करना होगा? क्या समय से पहले चुकाने पर कोई जुर्माना है?",
  "Can I take it to an independent mechanic and check the papers (license, violations)?": "क्या मैं इसे किसी स्वतंत्र मैकेनिक को दिखा सकता/सकती हूँ और काग़ज़ात (लाइसेंस, चालान) जाँच सकता/सकती हूँ?",
  "Is the contract registered, and who pays the maintenance and utilities?": "क्या कॉन्ट्रैक्ट रजिस्टर्ड है, और रखरखाव व बिलों का खर्च कौन देगा?",
  "Can I get everything agreed in writing?": "क्या मुझे तय हुई सारी बातें लिखित में मिल सकती हैं?",
  "No price was found in the offer.": "ऑफ़र में कोई कीमत नहीं मिली।",
  "The installments add up to less than the cash price — one of them was probably misread.": "किस्तों का जोड़ नकद कीमत से कम बैठ रहा है — शायद उनमें से कोई संख्या गलत पढ़ी गई है।",
  "The number of months is written but not the monthly amount.": "महीनों की संख्या लिखी है लेकिन मासिक किस्त की रकम नहीं लिखी है।",
  "Do you mean: ": "क्या आपका मतलब यह है: ",
  "Write a short, polite message to the seller (3–5 lines), ready to send on WhatsApp. No preamble, no explanation — only the message.": "विक्रेता के लिए एक छोटा, विनम्र मैसेज (3–5 पंक्तियाँ) लिखें, जो WhatsApp पर भेजने के लिए तैयार हो। कोई भूमिका नहीं, कोई व्याख्या नहीं — सिर्फ़ मैसेज।",
  "List every amount and important figure": "हर रकम और ज़रूरी आँकड़े की सूची बनाएँ",
  "List all dates and deadlines": "सभी तारीखों और अंतिम समय-सीमाओं की सूची बनाएँ",
  "had foul and 2 eggs for breakfast": "नाश्ते में फ़ूल और 2 अंडे खाए",
  "spent 150 on lunch": "दोपहर के खाने पर 150 खर्च किए",
  "remind me tomorrow at 9 to call Hassan": "कल 9 बजे Hassan को कॉल करने की याद दिलाएँ",
  "drank 2 glasses of water": "2 गिलास पानी पिया",
  "Ahmed owes me 12,000, 1,000 a month": "Ahmed पर मेरे 12,000 बाकी हैं, 1,000 हर महीने",
  "took my insulin": "मैंने अपनी इंसुलिन ले ली",
  "— very high. If you have chest pain, a headache or blurred vision, get help now.": "— बहुत ज़्यादा है। अगर आपको सीने में दर्द, सिरदर्द या धुँधला दिख रहा है, तो तुरंत डॉक्टर की मदद लें।",
  "— high; check it again later.": "— ज़्यादा है; थोड़ी देर बाद इसे फिर से जाँचें।",
  "— low.": "— कम है।",
  "No family space yet — open Family to start one.": "अभी कोई परिवार स्पेस नहीं है — शुरू करने के लिए परिवार खोलें।",
  "That medicine isn't in Family health.": "वह दवाई परिवार की सेहत में दर्ज नहीं है।",
  "Start the family space first (Family → your name) — then this goes on the shared list.": "पहले परिवार स्पेस शुरू करें (परिवार → आपका नाम) — फिर यह साझा सूची में चला जाएगा।",
  "Already on the family list.": "यह पहले से परिवार की सूची में है।",
