  "No sugar / salt data for today's foods — packaged products (barcode or search) carry them.": "आज के खाने के लिए चीनी / नमक का डेटा नहीं है — पैकेज्ड प्रोडक्ट (बारकोड या खोज) में यह जानकारी होती है।",
  "Times by the sun's position (Egyptian General Authority angles), ±3 min — follow your local mosque's call.": "सूरज की स्थिति के अनुसार समय (मिस्री प्राधिकरण के कोण), ±3 मिनट — अपनी स्थानीय मस्जिद की अज़ान का पालन करें।",
  "From Family health. Not medical advice — your doctor sets your insulin.": "परिवार की सेहत से। यह डॉक्टरी सलाह नहीं है — आपकी इंसुलिन की मात्रा आपके डॉक्टर तय करते हैं।",
