  "Body fat (tape measure)": "शरीर की चर्बी (इंची टेप से)",
  "US Navy method: waist at the navel (women: narrowest), neck below the Adam's apple — ±3 %. The trend matters more than one number.": "US नेवी तरीका: नाभि पर कमर (महिलाएँ: सबसे पतला हिस्सा), गले के उभार के नीचे गर्दन — ±3 %। एक संख्या से ज़्यादा रुझान मायने रखता है।",
  "Drink a glass of water": "एक गिलास पानी पिएँ",
  "Reminders on: meals and water": "रिमाइंडर चालू: भोजन और पानी",
