  "Istanbul": "इस्तांबुल",
  "Break the fast with water and 2–3 dates, then pray before the main meal — the stomach settles.": "पानी और 2–3 खजूर से रोज़ा खोलें, फिर मुख्य भोजन से पहले नमाज़ पढ़ें — इससे पेट को आराम मिलता है।",
  "Suhoor: slow food (ful, eggs, oats, yogurt) and water; little salt and sugar so you're less thirsty.": "सहरी: धीरे पचने वाला खाना (फ़ूल, अंडे, ओट्स, दही) और पानी; नमक और चीनी कम रखें ताकि प्यास कम लगे।",
  "Keep fried food and konafa/qatayef for once or twice a week.": "तला हुआ खाना और कुनाफ़ा/क़तायफ़ हफ़्ते में सिर्फ़ एक या दो बार ही खाएँ।",
  "Essential": "आवश्यक",
  "Athletic": "एथलेटिक",
  "Fit": "फ़िट",
  "Average": "औसत",
  "High": "ज़्यादा",
  "Next week: protein at every meal (eggs, chicken, fish, Greek yogurt, lentils).": "अगले हफ़्ते: हर भोजन में प्रोटीन लें (अंडे, चिकन, मछली, ग्रीक योगर्ट, दालें)।",
  "Log at least 5 days — a week's picture needs them.": "कम से कम 5 दिन दर्ज करें — पूरे हफ़्ते की तस्वीर के लिए यह ज़रूरी है।",
  "Log your breakfast": "अपना नाश्ता दर्ज करें",
  "Log your lunch": "अपना दोपहर का खाना दर्ज करें",
  "Log your dinner": "अपना रात का खाना दर्ज करें",
  "🛒 Shopping list for the week": "🛒 हफ़्ते के लिए खरीदारी की सूची",
  "Digesting — blood sugar rises": "पाचन चालू — ब्लड शुगर बढ़ता है",
  "Blood sugar falls back to normal": "ब्लड शुगर वापस सामान्य होता है",
  "Glycogen stores are being used": "ग्लाइकोजन भंडार का उपयोग हो रहा है",
  "Fat burning begins": "चर्बी गलना (फ़ैट बर्निंग) शुरू होता है",
  "Fat burning is in full swing": "चर्बी गलना पूरे ज़ोरों पर है",
