  "Tell me about yourself.": "मुझे अपने बारे में बताएँ।",
  "Why do you want this job?": "आप यह नौकरी क्यों करना चाहते हैं?",
  "Tell me about a problem you solved at work.": "काम पर आपके द्वारा हल की गई किसी समस्या के बारे में बताएँ।",
  "What is your biggest strength — with an example?": "आपकी सबसे बड़ी खूबी क्या है — एक उदाहरण के साथ बताएँ?",
  "Tell me about a time you made a mistake. What did you do?": "ऐसे किसी समय के बारे में बताएँ जब आपसे कोई गलती हुई हो। आपने क्या किया?",
  "Where do you see yourself in three years?": "तीन साल बाद आप खुद को कहाँ देखते हैं?",
  "Do you have any questions for us?": "क्या आप हमसे कोई सवाल पूछना चाहते हैं?",
  "Walk me through a project you built. What was hardest?": "अपने बनाए किसी प्रोजेक्ट के बारे में विस्तार से बताएँ। सबसे कठिन क्या था?",
  "How do you make sure your code works?": "आप यह कैसे सुनिश्चित करते हैं कि आपका कोड सही काम कर रहा है?",
  "Tell me about an analysis that changed a decision.": "ऐसे किसी विश्लेषण के बारे में बताएँ जिसने कोई फ़ैसला बदल दिया हो।",
  "How do you check that data is correct?": "आप यह कैसे जाँचते हैं कि डेटा सही है?",
  "How do you close the month?": "आप महीने का हिसाब कैसे बंद करते हैं?",
  "Tell me about a reconciliation that didn't match.": "ऐसे किसी मिलान के बारे में बताएँ जो मैच नहीं हो रहा था।",
  "Tell me about your best month. What did you do differently?": "अपने सबसे अच्छे महीने के बारे में बताएँ। आपने क्या अलग किया था?",
  "How do you handle a client who says it's too expensive?": "जो क्लाइंट कहता है कि कीमत बहुत ज़्यादा है, उसे आप कैसे संभालते हैं?",
  "Tell me about a campaign and its results.": "किसी कैंपेन और उसके नतीजों के बारे में बताएँ।",
  "How do you decide where to spend the budget?": "आप यह कैसे तय करते हैं कि बजट कहाँ खर्च करना है?",
  "Tell me about an angry customer you helped.": "किसी नाराज़ ग्राहक के बारे में बताएँ जिसकी आपने मदद की।",
  "What do you do when you don't know the answer?": "जब आपको किसी सवाल का जवाब नहीं पता होता तो आप क्या करते हैं?",
  "Tell me about a time a patient's condition changed quickly.": "ऐसे किसी समय के बारे में बताएँ जब किसी मरीज़ की हालत तेज़ी से बदली हो।",
  "How do you help a student who is falling behind?": "जो छात्र पढ़ाई में पिछड़ रहा हो, आप उसकी मदद कैसे करते हैं?",
  "Tell me about a project that was late. What did you do?": "ऐसे किसी प्रोजेक्ट के बारे में बताएँ जिसमें देरी हो रही थी। आपने क्या किया?",
  "Walk me through a design from brief to final.": "शुरुआती ब्रीफ़ से लेकर अंतिम रूप तक किसी डिज़ाइन की प्रक्रिया बताएँ।",
  "How do you find good candidates for a hard role?": "किसी कठिन पद के लिए आप अच्छे उम्मीदवार कैसे ढूँढते हैं?",
  "Tell me about a site problem you solved.": "साइट की किसी समस्या के बारे में बताएँ जिसे आपने हल किया।",
  "What do you do if a delivery can't be completed?": "अगर कोई डिलीवरी पूरी न हो सके तो आप क्या करते हैं?",
  "How do you plan a lift near the chart's limit?": "चार्ट की अधिकतम सीमा के करीब किसी लिफ़्ट की योजना आप कैसे बनाते हैं?",
  "How do you keep quality during a rush?": "भीड़-भाड़ के समय आप क्वालिटी कैसे बनाए रखते हैं?",
  "How do you handle many urgent tasks at once?": "एक साथ कई ज़रूरी काम आने पर आप उन्हें कैसे संभालते हैं?",
  "A clear story: what happened → what you did → the result.": "एक स्पष्ट कहानी: क्या हुआ → आपने क्या किया → नतीजा क्या रहा।",
  " is missing.": " अधूरा है।",
  "A number makes the result believable.": "कोई संख्या जोड़ने से नतीजा विश्वसनीय लगता है।",
  "Add a number to the result (how many, how much, how fast).": "नतीजे में कोई संख्या जोड़ें (कितने, कितना, कितनी तेज़ी से)।",
  "It matches what your CV says.": "यह आपके CV में लिखी बातों से मेल खाता है।",
  "Tell every answer as a story: what happened, what YOU did, and the result with a number.": "हर जवाब को एक कहानी की तरह बताएँ: क्या हुआ, आपने क्या किया, और संख्या के साथ उसका नतीजा।",
  "Replace “um” and “like” with a short pause — a second of silence sounds more confident.": "“अं” और “मतलब” जैसे फ़िलर शब्दों की जगह थोड़ा रुकें — एक सेकंड की शांति ज़्यादा आत्मविश्वास दिखाती है।",
  "Say “I did” and “it worked” instead of “I think” and “maybe”.": "“मुझे लगता है” और “शायद” के बजाय “मैंने किया” और “यह कामयाब रहा” कहें।",
  "Keep a steady pace: 110–170 words a minute.": "बोलने की रफ़्तार संतुलित रखें: 110–170 शब्द प्रति मिनट।",
